Q(rel, cov) =
\begin{cases}
1.00 & \text{if } (rel, cov) = \text{3E} \\
0.75 & \text{if } (rel, cov) \in \{\text{2E, 3L}\} \\
0.50 & \text{if } (rel, cov) \in \{\text{1E, 2L, 2S}\} \\
0.25 & \text{if } (rel, cov) \in \{\text{1S, 1L}\} \\
0.00 & \text{if } (rel, cov) = \text{0N}
\end{cases}
